	@Test
	void retainedPlanningPinDeclinesTheLaterPublishedDomain(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		seedQualifiedIriAndUnqualifiedLiteral(directory);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		HeldStore store = new HeldStore(directory, entered, release);
		SailRepository repository = new SailRepository(store);
		ExecutorService writer = Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon()
				.name("domain-old-pin-writer").factory());
		try (AutoCloseable cleanup = () -> {
			release.countDown();
			writer.shutdown();
			if (!writer.awaitTermination(10, TimeUnit.SECONDS)) {
				RETAINED.add(repository);
				throw new IllegalStateException("writer remains live; repository retained");
			}
			try {
				repository.shutDown();
			} catch (Exception | Error failure) {
				RETAINED.add(repository);
				throw failure;
			}
		}) {
			repository.init();
			assertTrue(entered.await(10, TimeUnit.SECONDS));
			LmdbSailStore backing = store.getBackingStore();
			ValueStore values = (ValueStore) backing.getValueFactory();
			TripleStore triples = backing.getTripleStore();
			long predicateId = values.getId(P);
			long iriId = values.getId(IRI_OBJECT);
			long literalId = values.getId(LITERAL_OBJECT);
			LmdbEstimatorRuntime runtime = assertInstanceOf(LmdbEvaluationStatistics.class,
					store.getSailStore().getEvaluationStatistics()).estimatorRuntime();
			LmdbPackedPredicateRangeProvider ranges = new LmdbPackedPredicateRangeProvider(runtime);
			try (LmdbSailStore.ReadView old = openView(backing);
					TripleStore.PlanningReadPin pin = runtime.pinPlanningReads(old.tripleTxn(), old.valueSnapshot())) {
				assertEquals(Set.of(iriId, literalId), objectIds(triples, old, predicateId));
				assertTrue(triples.getKnownRdfTermDomain(predicateId).isEmpty());
				writer.submit(() -> {
					try (var connection = repository.getConnection()) {
						connection.begin(IsolationLevels.SNAPSHOT);
						connection.remove(S2, P, LITERAL_OBJECT);
						connection.commit();
					}
				}).get(10, TimeUnit.SECONDS);
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
				assertEquals(Set.of(iriId, literalId), objectIds(triples, old, predicateId));
				assertTrue(triples.getKnownRdfTermDomain(predicateId).isEmpty(),
						"a continuously held old planning pin cannot inherit newer domain authority");
				assertTrue(triples.getPersistedRdfTermDomain(predicateId).isEmpty());
				assertFalse(ranges.describeObjectRange(P, new PackedPredicateRange()));
			}
			try (LmdbSailStore.ReadView current = openView(backing);
					TripleStore.PlanningReadPin pin = runtime.pinPlanningReads(current.tripleTxn(), current.valueSnapshot())) {
				assertEquals(Set.of(iriId), objectIds(triples, current, predicateId));
				assertEquals(Optional.of(RdfTermDomain.IRI), triples.getKnownRdfTermDomain(predicateId));
			}
		}
	}

	private static LmdbSailStore.ReadView openView(LmdbSailStore backing) {
		try (LmdbSailStore.DatasetAdmission admission = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
			admission.view().requireDictionaryTermSnapshot();
			return admission.view().retain();
		}
	}

	private static Set<Long> objectIds(TripleStore triples, LmdbSailStore.ReadView view, long predicate) throws IOException {
		Set<Long> ids = new HashSet<>();
		try (RecordIterator records = triples.getTriples(view.tripleTxn(), -1, predicate, -1, -1, true)) {
			long[] row;
			while ((row = records.next()) != null) {
				ids.add(row[2]);
			}
		}
		return ids;
	}

	private static void seedQualifiedIriAndUnqualifiedLiteral(Path directory) throws Exception {
		LmdbStore first = new LmdbStore(directory.toFile(), config(true));
		first.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(first, 30, TimeUnit.SECONDS);
			try (var connection = first.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(S1, P, IRI_OBJECT);
				connection.commit();
			}
		} finally {
			first.shutDown();
		}
		LmdbStore disabled = new LmdbStore(directory.toFile(), config(false));
		disabled.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(disabled, 30, TimeUnit.SECONDS);
			try (var connection = disabled.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(S2, P, LITERAL_OBJECT);
				connection.addStatement(S2, KEEP, LITERAL_OBJECT);
				connection.commit();
			}
			ValueStore values = (ValueStore) disabled.getBackingStore().getValueFactory();
			TripleStore triples = disabled.getBackingStore().getTripleStore();
			assertEquals(RdfTermDomain.IRI, rawPersistedDomain(triples.env, values.getId(P)),
					"disabled writes must leave a real stale IRI-only record for the old snapshot");
			assertFalse(triples.getKnownRdfTermDomain(values.getId(P)).isPresent());
		} finally {
			disabled.shutDown();
		}
	}

	private static RdfTermDomain rawPersistedDomain(long env, long predicateId) {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer ptr = stack.mallocPointer(1);
			nativeSuccess(mdb_txn_begin(env, 0L, MDB_RDONLY, ptr));
			long txn = ptr.get(0);
			try {
				var dbi = stack.mallocInt(1);
				nativeSuccess(mdb_dbi_open(txn, TripleStore.PREDICATE_OBJECT_DOMAINS_DB, 0, dbi));
				ByteBuffer keyBytes = stack.malloc(9);
				Varint.writeUnsigned(keyBytes, predicateId);
				keyBytes.flip();
				MDBVal key = MDBVal.malloc(stack).mv_data(keyBytes);
				MDBVal data = MDBVal.malloc(stack);
				nativeSuccess(mdb_get(txn, dbi.get(0), key, data));
				ByteBuffer bytes = data.mv_data();
				assertNotNull(bytes);
				return RdfTermDomain.fromMask(bytes.getLong(bytes.position() + Long.BYTES));
			} finally {
				mdb_txn_abort(txn);
			}
		}
	}

	private static void nativeSuccess(int result) {
		assertEquals(MDB_SUCCESS, result, () -> mdb_strerror(result));
	}

	private static LmdbStoreConfig config(boolean enabled) {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false).setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF).setPredicateGuaranteeIndexEnabled(enabled)
				.setPredicateGuaranteeIndexAutoRebuild(true);
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		private HeldStore(Path directory, CountDownLatch entered, CountDownLatch release) {
			super(directory.toFile(), config(true));
			this.entered = entered;
			this.release = release;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
